const ARCHIVED_COMMIT='67d9c290684f06ba2bda8a7694def1e9e4448381';
const ARCHIVED_CLIMATE_SOURCE="// ---------------------------------------------------------------------------\n// CLIMATE — the world's macro-weather as composable scalar FIELDS (axes).\n//\n// The biome heat map's structural backbone: every axis (temperature, moisture,\n// wildness, maritime…) is a named 0..1 field over node space, built from a\n// stack of DATA layers — smooth value noise, a radial gradient from home, an\n// ocean-adjacency probe, a per-landmass flavor bias, flat constants. Biomes\n// declare AFFINITY envelopes over these axes (the presence-envelope math from\n// engine/presence.ts, evaluated on axis values instead of levels), and the\n// biome field multiplies seed weight × affinity per Voronoi cell — so deserts\n// coalesce where it runs hot and dry, tundra claims the frigid distances,\n// hazard biomes bloom in the deep wild, and a far continent reached by voyage\n// carries its own hash-flavored signature (a scorched landmass, a drowned one).\n//\n// Dimensions register their own axis OVERRIDES (the Underworld runs hot and\n// arid), so one machinery drives the surface heat map, every parallel\n// worldmass, and any future plane — adding an axis, a band, a biome affinity,\n// or a dimension override is pure data. Everything is deterministic per\n// (coord, seed): same world on every machine, every reload.\n//\n// Pure leaf: imports only the coord type, the continent field (a sibling\n// leaf), and engine/presence (itself a zero-import leaf, shared by design).\n// ---------------------------------------------------------------------------\n\nimport type { MapCoord } from './coords';\nimport { continentCellAt, continentSeedFrom } from './continents';\nimport { presenceMul, type LevelEnvelope } from '../engine/presence';\n\n// --- layers -----------------------------------------------------------------\n\n/** One additive contribution to an axis. All fields are data; add a layer kind\n *  by extending this union + one case in `layerValue`. */\nexport type ClimateLayer =\n  /** Smooth 2-lattice value noise, centered: contributes ±amp. `cell` is the\n   *  feature size in node units; `salt` decorrelates two noise layers on the\n   *  same axis. */\n  | { kind: 'noise'; cell: number; amp: number; salt?: number }\n  /** RIDGED noise: (1 − |2n − 1|)², 0..1 — sharp crests along the noise\n   *  lattice's mid-lines (mountain-range spines, not blobs). Contributes\n   *  0..+amp. The elevation axis' backbone. */\n  | { kind: 'ridge'; cell: number; amp: number; salt?: number }\n  /** Radial gradient from a NAMED anchor (default: the world origin, home):\n   *  0 inside `innerRadius`, rising to +amp over `span`. The \"danger\n   *  geography\" tie — the same shape as the level field's floor. An anchor\n   *  that is not (yet) installed reads FAR — the layer contributes its full\n   *  amp — so an axis like 'civic' safely means \"no capital anywhere\" until\n   *  the pole is derived at world boot, instead of misfiring at (0,0). */\n  | { kind: 'radial'; innerRadius: number; span: number; amp: number; anchor?: string }\n  /** Radial DEPRESSION around a named anchor: subtracts up to `amp` at the\n   *  anchor, fading to 0 over `span` — how a SECOND heart of civilization\n   *  tames its surroundings without moving home's own gradient (the capital\n   *  pole rides this on wildness). Missing anchor = no contribution. */\n  | { kind: 'basin'; anchor: string; span: number; amp: number; innerRadius?: number }\n  /** Ocean adjacency: probes the continent field around the point; contributes\n   *  up to +amp when the sea is near (1 when ON open water — islands read as\n   *  fully maritime). `probe` is the sampling reach in node units. */\n  | { kind: 'coastal'; probe: number; amp: number }\n  /** Per-LANDMASS flavor: a stable hash bias in ±spread for the continent the\n   *  point belongs to. The HOME landmass is pinned to 0 so the starting\n   *  continent stays the baseline; every voyage landfall inherits a coherent\n   *  signature instead of the same mix everywhere. */\n  | { kind: 'landmass'; spread: number }\n  /** A flat push — dimension overrides mostly ride this. */\n  | { kind: 'const'; value: number };\n\nexport interface ClimateAxisDef {\n  id: string;\n  label: string;\n  /** Resting value before layers stack (clamped 0..1 after). */\n  base: number;\n  layers: ClimateLayer[];\n}\n\n/** The AXES registry — open; packages/dimensions may add their own axes\n *  (a 'corruption' axis an event pumps, a 'depth' axis for an abyss plane). */\nexport const CLIMATE_AXES: Record<string, ClimateAxisDef> = {};\n\nexport function registerClimateAxis(def: ClimateAxisDef, overwrite = false): void {\n  if (!overwrite && CLIMATE_AXES[def.id] !== undefined) return;\n  CLIMATE_AXES[def.id] = def;\n}\n\n// The default surface axes. Feature sizes sit an octave above the biome\n// Voronoi (cellSpan 260) so one climate region spans several biome blobs —\n// the heat map reads as REGIONS of desert, not desert confetti.\nregisterClimateAxis({\n  id: 'temperature', label: 'Temperature', base: 0.5,\n  layers: [\n    { kind: 'noise', cell: 1500, amp: 0.32 },\n    { kind: 'noise', cell: 520, amp: 0.1, salt: 0x7e39 },\n    { kind: 'landmass', spread: 0.28 },\n  ],\n});\nregisterClimateAxis({\n  id: 'moisture', label: 'Moisture', base: 0.5,\n  layers: [\n    { kind: 'noise', cell: 1200, amp: 0.3, salt: 0x11c1 },\n    { kind: 'noise', cell: 430, amp: 0.08, salt: 0x2f77 },\n    { kind: 'coastal', probe: 700, amp: 0.22 },\n    { kind: 'landmass', spread: 0.22 },\n  ],\n});\nregisterClimateAxis({\n  // How far from the SETTLED world a point sits — the exotic/hazard gradient.\n  // Near home it reads ~base (settled); it saturates in the far wilds, so\n  // flesh/crystal/volcanic country blooms with distance and a far voyage\n  // landfall skews strange. The radial twin of the level field.\n  id: 'wildness', label: 'Wildness', base: 0.12,\n  layers: [\n    { kind: 'radial', innerRadius: 100, span: 520, amp: 0.85 },\n    // THE CAPITAL TAMES ITS COUNTRY: a second heart of civilization presses\n    // wildness back down around the capital pole (world/civics.ts derives it\n    // per seed; the sim installs the 'capital' anchor at boot). Sized against\n    // the radial above: at the pole the far-wilds ~0.97 dips to ~0 — so the\n    // settled biomes' own wildness affinities (metropolis ≤~0.4, farmland\n    // ≤~0.58, downs ≤~0.82) LIVE there and stage city → crofts → sheep downs\n    // → wilds outward with no extra machinery: at span 850 the city rows die\n    // ~365 out, crops ~520, downs ~700 — the capital ring's worked country\n    // gets real acreage before the wilds resume. A near-rolled pole's basin\n    // can overlap home's calm and read as one settled vale; a far roll\n    // leaves a wild march between — deliberate per-seed world character. No\n    // anchor (menus, pole-less contexts) = no basin: the old field,\n    // byte-identical.\n    { kind: 'basin', anchor: 'capital', span: 850, amp: 1.0 },\n    { kind: 'noise', cell: 800, amp: 0.15, salt: 0x5abd },\n  ],\n});\nregisterClimateAxis({\n  // Ocean adjacency as its own axis, so coastal biomes (beach/isle) hug real\n  // shores instead of rolling anywhere the flat weights allowed.\n  id: 'maritime', label: 'Maritime', base: 0,\n  layers: [\n    { kind: 'coastal', probe: 620, amp: 1 },\n  ],\n});\nregisterClimateAxis({\n  // PURE distance-from-home, noise-free BY DESIGN: wildness carries ±0.15\n  // noise with ~800-unit features, so a whole world's near-home readings\n  // shift together — any absolute wildness threshold is seed-shifty. The\n  // hearth axis is the deterministic geometry lever for anything that must\n  // hold at home in EVERY world (the home-shire field tilt rides it; future\n  // near-home event gates can too). 0 at the town, 1 by ~640 map units.\n  id: 'hearth', label: 'Hearth', base: 0,\n  layers: [\n    { kind: 'radial', innerRadius: 0, span: 640, amp: 1 },\n  ],\n});\nregisterClimateAxis({\n  // THE LAND'S VERTICAL TRUTH — the relief fabric's backbone (world/relief.ts\n  // traces rivers DOWN this field; mountain biomes claim its heights, marsh\n  // its hollows). Seam-free and lazy like every axis: ridged crests give\n  // ranges their spines, the coastal layer pulls the land DOWN toward every\n  // shore (rivers seek the sea for free), and the noise octaves break the\n  // slopes. Sampled hot via climateAxisAt — keep this stack lean.\n  id: 'elevation', label: 'Elevation', base: 0.52,\n  layers: [\n    { kind: 'noise', cell: 1700, amp: 0.3, salt: 0xe1e1 },\n    { kind: 'noise', cell: 560, amp: 0.1, salt: 0xe1e2 },\n    { kind: 'ridge', cell: 980, amp: 0.26, salt: 0xe1e3 },\n    { kind: 'coastal', probe: 700, amp: -0.55 },\n  ],\n});\nregisterClimateAxis({\n  // Distance-from-the-CAPITAL: hearth's civic twin — 0 at the capital pole\n  // (world/civics.ts derives it per seed; the sim installs the anchor at\n  // boot), 1 by ~640 units out, and 1 EVERYWHERE while no pole is installed\n  // (an absent anchor reads far, so the capital field bands go inert instead\n  // of misfiring at the world origin). Noise-free for hearth's reason: band\n  // radii must be true geometry in every world.\n  id: 'civic', label: 'Civic', base: 0,\n  layers: [\n    { kind: 'radial', anchor: 'capital', innerRadius: 0, span: 640, amp: 1 },\n  ],\n});\n\n/** Structural tunables. `origin` anchors un-named radial layers (home = the\n *  town's canonical map coord — the world grows outward from it); `anchors`\n *  are NAMED points radial/basin layers key on by `anchor` (the capital pole\n *  installs 'capital' at world boot). */\nexport const CLIMATE_CFG = {\n  origin: { x: 0, y: 0 } as MapCoord,\n  anchors: {} as Record<string, MapCoord | null>,\n};\n\n/** Downstream caches keyed on climate readings (the biome field's cell-pick\n *  memo) register here; any origin/anchor change flushes them. Boot-time\n *  events only — the cost is a rare re-fill, the win is that a re-anchored\n *  world can never serve picks computed under the old geometry. */\nconst invalidationListeners: (() => void)[] = [];\nexport function registerClimateInvalidation(cb: () => void): void {\n  invalidationListeners.push(cb);\n}\nfunction invalidateClimate(): void {\n  homeCellMemo = null; // the home landmass derives from the origin — re-resolve\n  for (const cb of invalidationListeners) cb();\n}\n\n/** Anchor radial layers on home. Called once at boot by WorldSim with the\n *  town's STATIC canonical map coord (the level field's exact pattern) —\n *  static data, so host and clients agree without any replication. */\nexport function setClimateOrigin(c: MapCoord): void {\n  CLIMATE_CFG.origin = { x: c.x, y: c.y };\n  invalidateClimate();\n}\n\n/** Install (or clear) a NAMED anchor for radial/basin layers. Same law as the\n *  origin: derived from static/seed data only — never replicated, so host,\n *  clients and reloads agree by construction. */\nexport function setClimateAnchor(name: string, c: MapCoord | null): void {\n  CLIMATE_CFG.anchors[name] = c ? { x: c.x, y: c.y } : null;\n  invalidateClimate();\n}\n\n// --- bands ------------------------------------------------------------------\n\n/** What a biome affinity carries per axis: an inline envelope over the axis'\n *  0..1 value, or the name of a registered band for that axis. */\nexport type ClimateSpec = string | LevelEnvelope;\n\n/** Named affinity bands PER AXIS — the shared climate vocabulary ('desert is\n *  hot + arid' reads at a glance and retunes in one place). Open registry. */\nexport const CLIMATE_BANDS: Record<string, Record<string, LevelEnvelope>> = {\n  temperature: {\n    frigid: { to: 0.18, fadeOut: 0.14 },\n    cold: { to: 0.35, fadeOut: 0.15 },\n    mild: { from: 0.25, fadeIn: 0.15, to: 0.7, fadeOut: 0.15 },\n    warm: { from: 0.5, fadeIn: 0.15 },\n    hot: { from: 0.62, fadeIn: 0.14 },\n    scorching: { from: 0.75, fadeIn: 0.12 },\n  },\n  moisture: {\n    arid: { to: 0.25, fadeOut: 0.12 },\n    dry: { to: 0.45, fadeOut: 0.15 },\n    damp: { from: 0.4, fadeIn: 0.18 },\n    wet: { from: 0.6, fadeIn: 0.15 },\n    drowned: { from: 0.8, fadeIn: 0.1 },\n  },\n  wildness: {\n    settled: { to: 0.3, fadeOut: 0.18 },\n    frontier: { from: 0.12, fadeIn: 0.12, to: 0.72, fadeOut: 0.18 },\n    deepwild: { from: 0.55, fadeIn: 0.18 },\n  },\n  maritime: {\n    inland: { to: 0.12, fadeOut: 0.15 },\n    shorebound: { from: 0.4, fadeIn: 0.25 },\n  },\n};\n\nexport function registerClimateBand(\n  axis: string, name: string, env: LevelEnvelope, overwrite = false,\n): void {\n  const bands = (CLIMATE_BANDS[axis] ??= {});\n  if (!overwrite && bands[name] !== undefined) return;\n  bands[name] = env;\n}\n\n// --- dimension overrides ------------------------------------------------------\n\nexport interface DimensionAxisOverride {\n  /** Replaces the axis' resting value in this dimension. */\n  base?: number;\n  /** Replaces the axis' layer stack in this dimension (omit = keep surface layers). */\n  layers?: ClimateLayer[];\n}\n\n/** Per-dimension axis overrides, registered by dimensions.ts at boot (kept as\n *  a registry HERE so this leaf never imports the dimension registry). */\nconst DIMENSION_CLIMATE: Record<string, Record<string, DimensionAxisOverride>> = {};\n\nexport function registerDimensionClimate(\n  dimId: string, axes: Record<string, DimensionAxisOverride>,\n): void {\n  DIMENSION_CLIMATE[dimId] = { ...DIMENSION_CLIMATE[dimId], ...axes };\n}\n\nexport function dimensionClimateOf(dimId: string): Record<string, DimensionAxisOverride> | undefined {\n  return DIMENSION_CLIMATE[dimId];\n}\n\n// --- sampling ----------------------------------------------------------------\n\n/** Integer hash (Rng's family) → deterministic across host / client / reload. */\nfunction hashCell(a: number, b: number, seed: number): number {\n  let h = (seed ^ 0x9e3779b9) >>> 0;\n  h = Math.imul(h ^ (a | 0), 0x85ebca6b) >>> 0;\n  h = Math.imul(h ^ (b | 0), 0xc2b2ae35) >>> 0;\n  h ^= h >>> 13; h = Math.imul(h, 0x27d4eb2f) >>> 0; h ^= h >>> 15;\n  return h >>> 0;\n}\n\nconst hash01 = (x: number, y: number, seed: number): number => hashCell(x, y, seed) / 0x100000000;\n\n/** Smooth (smoothstep-bilinear) value noise, 0..1 — the level field's idiom. */\nfunction valueNoise(x: number, y: number, cell: number, seed: number): number {\n  const gx = Math.floor(x / cell), gy = Math.floor(y / cell);\n  const fx = x / cell - gx, fy = y / cell - gy;\n  const sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy);\n  const a = hash01(gx, gy, seed), b = hash01(gx + 1, gy, seed);\n  const c = hash01(gx, gy + 1, seed), d = hash01(gx + 1, gy + 1, seed);\n  return (a + (b - a) * sx) * (1 - sy) + (c + (d - c) * sx) * sy;\n}\n\n/** Stable per-axis salt so axes decorrelate on the shared world seed. */\nfunction axisSalt(id: string): number {\n  let h = 0x811c9dc5;\n  for (let i = 0; i < id.length; i++) h = Math.imul(h ^ id.charCodeAt(i), 0x01000193) >>> 0;\n  return h >>> 0;\n}\n\nconst clamp01 = (v: number): number => (v < 0 ? 0 : v > 1 ? 1 : v);\n\n// The origin's WINNING continent cell per seed (memoized — one world, one home).\nlet homeCellMemo: { seed: number; gx: number; gy: number } | null = null;\nfunction homeCellFor(contSeed: number): { gx: number; gy: number } {\n  if (!homeCellMemo || homeCellMemo.seed !== contSeed) {\n    const c = continentCellAt(CLIMATE_CFG.origin, contSeed);\n    homeCellMemo = { seed: contSeed, gx: c.gx, gy: c.gy };\n  }\n  return homeCellMemo;\n}\n\n/** Continent info shared across an axis stack's layers (probed lazily). The\n *  coastal cache keys by PROBE REACH — two axes declaring different reaches\n *  (moisture 700, maritime 620) each get their own sample; a single slot once\n *  silently served the first-computed reach to every later axis. */\ninterface ContinentProbe {\n  cell: { gx: number; gy: number; kind: 'land' | 'ocean' | 'bridge' } | null;\n  coastal: Map<number, number> | null;\n}\n\nfunction layerValue(\n  layer: ClimateLayer, coord: MapCoord, seed: number, salt: number, probe: ContinentProbe,\n): number {\n  switch (layer.kind) {\n    case 'noise':\n      return (valueNoise(coord.x, coord.y, layer.cell, (seed ^ salt ^ (layer.salt ?? 0)) >>> 0) - 0.5) * 2 * layer.amp;\n    case 'ridge': {\n      const n = valueNoise(coord.x, coord.y, layer.cell, (seed ^ salt ^ (layer.salt ?? 0)) >>> 0);\n      const crest = 1 - Math.abs(2 * n - 1);\n      return crest * crest * layer.amp;\n    }\n    case 'radial': {\n      const at = layer.anchor !== undefined ? CLIMATE_CFG.anchors[layer.anchor] : CLIMATE_CFG.origin;\n      if (!at) return layer.amp; // uninstalled anchor reads FAR — full contribution\n      const dx = coord.x - at.x, dy = coord.y - at.y;\n      const d = Math.sqrt(dx * dx + dy * dy);\n      return clamp01((d - layer.innerRadius) / layer.span) * layer.amp;\n    }\n    case 'basin': {\n      const at = CLIMATE_CFG.anchors[layer.anchor];\n      if (!at) return 0; // no anchor installed — the basin doesn't exist\n      const dx = coord.x - at.x, dy = coord.y - at.y;\n      const d = Math.sqrt(dx * dx + dy * dy);\n      return -(1 - clamp01((d - (layer.innerRadius ?? 0)) / layer.span)) * layer.amp;\n    }\n    case 'coastal': {\n      const cache = (probe.coastal ??= new Map<number, number>());\n      let v = cache.get(layer.probe);\n      if (v === undefined) {\n        const center = (probe.cell ??= continentCellAt(coord, seed));\n        if (center.kind !== 'land') v = 1;\n        else {\n          let sea = 0;\n          for (let i = 0; i < 4; i++) {\n            const a = (i / 4) * Math.PI * 2;\n            const c = continentCellAt(\n              { x: coord.x + Math.cos(a) * layer.probe, y: coord.y + Math.sin(a) * layer.probe }, seed,\n            );\n            if (c.kind !== 'land') sea++;\n          }\n          v = clamp01((sea / 4) * 1.6);\n        }\n        cache.set(layer.probe, v);\n      }\n      return v * layer.amp;\n    }\n    case 'landmass': {\n      const cell = (probe.cell ??= continentCellAt(coord, seed));\n      // The HOME landmass — whichever macro cell actually WINS at the climate\n      // origin under this seed's jitter (never assumed to be cell (0,0): the\n      // town sits near a macro-cell corner, so any of the four neighbours can\n      // win) — is the unbiased baseline.\n      const home = homeCellFor(seed);\n      if (cell.gx === home.gx && cell.gy === home.gy) return 0;\n      return (hash01(cell.gx, cell.gy, (seed ^ salt ^ 0x1a4d) >>> 0) - 0.5) * 2 * layer.spread;\n    }\n    case 'const':\n      return layer.value;\n  }\n}\n\n// The coastal/landmass layers read the CONTINENT field (seed derived once via\n// continentSeedFrom); noise/radial layers use the biome-field seed directly.\n\n/** One axis' composed value (the shared core of climateAt / climateAxisAt). */\nfunction axisValueAt(\n  axis: ClimateAxisDef, ov: DimensionAxisOverride | undefined,\n  coord: MapCoord, fieldSeed: number, contSeed: number, probe: ContinentProbe,\n): number {\n  let v = ov?.base ?? axis.base;\n  const salt = axisSalt(axis.id);\n  for (const layer of ov?.layers ?? axis.layers) {\n    v += layerValue(\n      layer, coord,\n      layer.kind === 'coastal' || layer.kind === 'landmass' ? contSeed : fieldSeed,\n      salt, probe,\n    );\n  }\n  return clamp01(v);\n}\n\n/** Every axis sampled at a coordinate, honoring the dimension's overrides.\n *  Pure + deterministic per (coord, fieldSeed, dimension). */\nexport function climateAt(\n  coord: MapCoord, fieldSeed: number, dimension = 'surface',\n): Record<string, number> {\n  const out: Record<string, number> = {};\n  const overrides = DIMENSION_CLIMATE[dimension];\n  const contSeed = continentSeedFrom(fieldSeed);\n  const probe: ContinentProbe = { cell: null, coastal: null };\n  for (const axis of Object.values(CLIMATE_AXES)) {\n    out[axis.id] = axisValueAt(axis, overrides?.[axis.id], coord, fieldSeed, contSeed, probe);\n  }\n  return out;\n}\n\n/** ONE axis sampled at a coordinate — the cheap lane for hot loops that need\n *  a single field (the relief tracer descends 'elevation' hundreds of times\n *  per river; paying for six axes per probe would be pure waste). Identical\n *  value to climateAt(...)[axisId] by construction (same core). */\nexport function climateAxisAt(\n  coord: MapCoord, fieldSeed: number, axisId: string, dimension = 'surface',\n): number {\n  const axis = CLIMATE_AXES[axisId];\n  if (!axis) return 0;\n  const probe: ContinentProbe = { cell: null, coastal: null };\n  return axisValueAt(\n    axis, DIMENSION_CLIMATE[dimension]?.[axisId], coord, fieldSeed, continentSeedFrom(fieldSeed), probe,\n  );\n}\n\n// --- affinity ----------------------------------------------------------------\n\nconst warnedBands = new Set<string>();\n\n/** Resolve a spec to its envelope (unknown band → warn once, always-on). */\nexport function climateEnvelope(axis: string, spec: ClimateSpec): LevelEnvelope {\n  if (typeof spec !== 'string') return spec;\n  const env = CLIMATE_BANDS[axis]?.[spec];\n  if (env) return env;\n  const key = `${axis}:${spec}`;\n  if (!warnedBands.has(key)) {\n    warnedBands.add(key);\n    console.warn(`[climate] unknown band '${spec}' on axis '${axis}' — treating as always-on`);\n  }\n  return {};\n}\n\n/** The affinity multiplier for a climate-spec map at sampled axis values —\n *  envelopes multiply across axes (all conditions must hold). Unknown axes\n *  are ignored here; validateClimate flags them at boot. */\nexport function climateAffinity(\n  spec: Record<string, ClimateSpec> | undefined, climate: Record<string, number>,\n): number {\n  if (!spec) return 1;\n  let m = 1;\n  for (const axis in spec) {\n    const v = climate[axis];\n    if (v === undefined) continue;\n    m *= presenceMul(climateEnvelope(axis, spec[axis]), v);\n    if (m <= 0) return 0;\n  }\n  return m;\n}\n\n// --- validation ---------------------------------------------------------------\n\n/** Boot validator: every climate-spec map references registered axes and (for\n *  string specs) registered bands. `specs` = [ownerLabel, spec] pairs from the\n *  caller (biomes, voyage islands, …) so this leaf stays source-agnostic. */\nexport function validateClimateSpecs(\n  specs: [string, Record<string, ClimateSpec> | undefined][],\n): string[] {\n  const bad: string[] = [];\n  for (const [owner, spec] of specs) {\n    if (!spec) continue;\n    for (const [axis, s] of Object.entries(spec)) {\n      if (!CLIMATE_AXES[axis]) bad.push(`${owner}: unknown axis '${axis}'`);\n      else if (typeof s === 'string' && !CLIMATE_BANDS[axis]?.[s]) {\n        bad.push(`${owner}: unknown band '${s}' on axis '${axis}'`);\n      }\n    }\n  }\n  return bad;\n}\n";
const ARCHIVED_CONTINENT_SOURCE="// ---------------------------------------------------------------------------\n// CONTINENTS — the world's LANDMASS field: a low-frequency jittered Voronoi\n// over node space (the biome field's idiom, an octave up) that partitions the\n// infinite map into continents separated by OCEAN, with occasional LAND\n// BRIDGES tying neighbours together. Pure + deterministic per (coord, seed):\n// the same coordinate is the same shore on every machine, every reload.\n//\n//   land    zones mint normally (a continent holds many biome regions)\n//   ocean   zones DON'T mint — a frontier reaching in becomes a PORT, and\n//           travel onward is by SEA (the Sail menu; Lost Ark port-hopping)\n//   bridge  a rare tested isthmus through the ocean between two landmasses —\n//           the walkable back door\n//\n// Every knob is data (CONTINENT_CFG): ocean spans, landmass scale, bridge\n// frequency — the \"configurable size spans of flexible ocean\" lever.\n// ---------------------------------------------------------------------------\n\nimport type { MapCoord } from './coords';\n\nexport interface ContinentCfg {\n  /** Macro-cell span in node units — the landmass scale (biome cells are 260;\n   *  a continent spans several biome regions). */\n  cellSpan: number;\n  /** Voronoi seed jitter (0..0.5) — organic coastlines, not squares. */\n  jitter: number;\n  /** Fraction of macro cells that are OCEAN — the sea-span lever. */\n  oceanFrac: number;\n  /** Chance an ocean cell wedged between two land cells firms into a BRIDGE. */\n  bridgeChance: number;\n}\n\nexport const CONTINENT_CFG: ContinentCfg = {\n  cellSpan: 1150,\n  jitter: 0.42,\n  oceanFrac: 0.38,\n  bridgeChance: 0.3,\n};\n\nexport interface ContinentInfo {\n  kind: 'land' | 'ocean' | 'bridge';\n  /** Stable landmass label (`cont_<gx>_<gy>` of the winning land seed) — the\n   *  port-routing key. null on open ocean. */\n  landmass: string | null;\n}\n\n/** THE one derivation of the continent seed from the biome-field seed — the\n *  landmass and biome layers are independent layouts of the same world, and\n *  every sampler (world, biomes, panels) must salt identically. */\nexport function continentSeedFrom(fieldSeed: number): number {\n  return (fieldSeed ^ 0x0cea11) >>> 0;\n}\n\nfunction hashCell(a: number, b: number, seed: number): number {\n  let h = (seed ^ 0x9e3779b9) >>> 0;\n  h = Math.imul(h ^ (a | 0), 0x85ebca6b) >>> 0;\n  h = Math.imul(h ^ (b | 0), 0xc2b2ae35) >>> 0;\n  h ^= h >>> 13; h = Math.imul(h, 0x27d4eb2f) >>> 0; h ^= h >>> 15;\n  return h >>> 0;\n}\n\nfunction cellIsLand(gx: number, gy: number, seed: number): boolean {\n  // The HOME NEIGHBORHOOD is always land — the town must never sit mid-ocean.\n  // The town's canonical coord lives near the corner of macro-cells\n  // (-1..0, -1..0) (cellSpan 1150, jitter 0.42), so ANY of those four can win\n  // the Voronoi at its coordinate depending on the seed; pinning only (0,0)\n  // left seeds where the town's actual winning cell rolled OCEAN (the map\n  // washed the town blue, frontiers gated into ports at the doorstep).\n  if (gx >= -1 && gx <= 0 && gy >= -1 && gy <= 0) return true;\n  return (hashCell(gx, gy, (seed ^ 0x51ed270b) >>> 0) / 0x100000000) >= CONTINENT_CFG.oceanFrac;\n}\n\n/** The WINNING macro cell at a coordinate — the landmass field's raw unit,\n *  exposed so sibling fields (climate's coastal/landmass-flavor layers) can\n *  key stable per-continent values without parsing label strings. */\nexport interface ContinentCell {\n  gx: number;\n  gy: number;\n  kind: 'land' | 'ocean' | 'bridge';\n}\n\n/** The RAW kind of one macro cell by its lattice address — the SEA FABRIC's\n *  fill substrate (world/seas.ts): continentCellAt answers \"which cell wins\n *  at a coordinate\"; this answers \"what is cell (gx,gy)\". Identical rolls to\n *  the winner path (one source of truth — continentCellAt delegates here).\n *  A bridge counts as NOT-water for sailing: its span blocks the boat, so\n *  two waters joined only under a bridge are separate SEAS. */\nexport function cellKind(gx: number, gy: number, seed: number): 'land' | 'ocean' | 'bridge' {\n  if (cellIsLand(gx, gy, seed)) return 'land';\n  // Bridge test: an ocean cell with land on OPPOSITE sides (either axis) may\n  // firm into an isthmus — hashed per cell so the bridge is stable world-wide.\n  const flanked =\n    (cellIsLand(gx - 1, gy, seed) && cellIsLand(gx + 1, gy, seed))\n    || (cellIsLand(gx, gy - 1, seed) && cellIsLand(gx, gy + 1, seed));\n  if (flanked && (hashCell(gx, gy, (seed ^ 0x2545f491) >>> 0) / 0x100000000) < CONTINENT_CFG.bridgeChance) {\n    return 'bridge';\n  }\n  return 'ocean';\n}\n\n/** The JITTERED SITE of a macro cell (its Voronoi seed point) — exported so\n *  the sea fabric's centroids/orderings share the exact geometry the winner\n *  search uses. */\nexport function cellSite(gx: number, gy: number, seed: number): MapCoord {\n  const span = CONTINENT_CFG.cellSpan, jit = CONTINENT_CFG.jitter;\n  const h = hashCell(gx, gy, seed);\n  return {\n    x: (gx + 0.5 + (((h & 0xffff) / 0xffff) - 0.5) * jit) * span,\n    y: (gy + 0.5 + ((((h >>> 16) & 0xffff) / 0xffff) - 0.5) * jit) * span,\n  };\n}\n\n/** The landmass field's winning cell at a node-space coordinate. Same 3×3\n *  jittered-Voronoi search as biomeAt; the winning seed's land/ocean roll\n *  decides (cellKind — the one source of truth). */\nexport function continentCellAt(coord: MapCoord, seed: number): ContinentCell {\n  const span = CONTINENT_CFG.cellSpan;\n  const cx = Math.floor(coord.x / span), cy = Math.floor(coord.y / span);\n  let bestD = Infinity, bestGx = 0, bestGy = 0;\n  for (let dx = -1; dx <= 1; dx++) {\n    for (let dy = -1; dy <= 1; dy++) {\n      const gx = cx + dx, gy = cy + dy;\n      const s = cellSite(gx, gy, seed);\n      const d = (s.x - coord.x) ** 2 + (s.y - coord.y) ** 2;\n      if (d < bestD) { bestD = d; bestGx = gx; bestGy = gy; }\n    }\n  }\n  return { gx: bestGx, gy: bestGy, kind: cellKind(bestGx, bestGy, seed) };\n}\n\n/** The landmass field at a node-space coordinate (label form of the cell). */\nexport function continentAt(coord: MapCoord, seed: number): ContinentInfo {\n  const cell = continentCellAt(coord, seed);\n  switch (cell.kind) {\n    case 'land': return { kind: 'land', landmass: `cont_${cell.gx}_${cell.gy}` };\n    case 'bridge': return { kind: 'bridge', landmass: `bridge_${cell.gx}_${cell.gy}` };\n    case 'ocean': return { kind: 'ocean', landmass: null };\n  }\n}\n\n/** March from a port coordinate across the ocean along a bearing until LAND —\n *  the \"chart a course\" landfall picker. Returns the first land coord (a\n *  little inland), or null if no land within `maxSteps`. Pure. */\nexport function landfallFrom(\n  from: MapCoord, angle: number, seed: number, maxSteps = 30,\n): MapCoord | null {\n  const step = CONTINENT_CFG.cellSpan * 0.45;\n  let sawOcean = false;\n  for (let i = 1; i <= maxSteps; i++) {\n    const c = { x: from.x + Math.cos(angle) * step * i, y: from.y + Math.sin(angle) * step * i };\n    const info = continentAt(c, seed);\n    if (info.kind !== 'land') { sawOcean = true; continue; }\n    if (sawOcean) {\n      // One more step inland so the landfall zone isn't itself a shoreline\n      // sliver — but only if the nudged point is STILL land (a thin island's\n      // far side is ocean again; landing on the verified coast beats sailing\n      // clean over the isle).\n      const inland = { x: c.x + Math.cos(angle) * step * 0.5, y: c.y + Math.sin(angle) * step * 0.5 };\n      return continentAt(inland, seed).kind === 'land' ? inland : c;\n    }\n  }\n  return null;\n}\n";
const ARCHIVED_PRESENCE_SOURCE="// ---------------------------------------------------------------------------\n// PRESENCE — level-banded spawn weighting, as data. The Oblivion \"leveled\n// list\" idea generalized: any monster table entry (zone packs, tileset packs,\n// faction rosters, package rosters, wildlife rows) and any MonsterDef may\n// carry a PresenceSpec — a weight-multiplier-vs-level ENVELOPE that decides\n// how present that monster is at a given spawn level (usually the zone's).\n//\n//   { to: 12, fadeOut: 4 }        — early fodder: full through 12, gone by 16\n//   { from: 20, fadeIn: 6 }       — a late arrival: absent below 14, full at 20\n//   { from: 5, to: 10, fadeOut: 5 } — a band: 5–10 at full, trailing off by 15\n//   { stops: [[1,3],[10,1],[18,0]] } — an arbitrary gradient (piecewise-linear)\n//   'late'                        — a named band from the open registry\n//\n// TWO LAYERS MULTIPLY: the entry's presence (per-list shaping — the same\n// monster can peak early in one roster and late in another) × the def's\n// presence (a global floor/ceiling wherever the id appears, even in plain\n// string[] pools). Presence shapes SELECTION only — explicit-id spawns\n// (bosses, summon verbs, composite parts, quest set-pieces) never consult it.\n//\n// This module is a pure leaf (no imports) so data files and the engine can\n// both use it without cycles. World.weightedPick(table, atLevel) is the one\n// runtime chokepoint; validate.ts sweeps tables for levels left empty.\n// ---------------------------------------------------------------------------\n\n/** A weight-multiplier-vs-level curve. Every field optional; {} = always 1. */\nexport interface LevelEnvelope {\n  /** First level at FULL presence — below it the fadeIn ramp (or a hard 0). */\n  from?: number;\n  /** Last level at FULL presence — above it the fadeOut ramp (or a hard 0). */\n  to?: number;\n  /** Levels BELOW `from` over which weight climbs 0→1 (default 0 = hard gate). */\n  fadeIn?: number;\n  /** Levels ABOVE `to` over which weight falls 1→0 (default 0 = hard gate). */\n  fadeOut?: number;\n  /** Arbitrary piecewise-linear gradient: sorted [level, mul] control points.\n   *  Outside the ends the curve HOLDS its end multiplier. Multiplies with the\n   *  from/to trapezoid when both are set (usually you use one or the other). */\n  stops?: [number, number][];\n  /** Flat multiplier on top of the curve (a band can also retune weight). */\n  mul?: number;\n}\n\n/** What data carries: an inline envelope, or the name of a registered band. */\nexport type PresenceSpec = string | LevelEnvelope;\n\n/** Anything an envelope-aware picker can chew on. */\nexport interface PresenceEntry { id: string; weight: number; presence?: PresenceSpec }\n\n/** NAMED BANDS — the shared vocabulary, an OPEN registry. Content data reads\n *  best when tiers are named once and retuned in one place ('early_only'\n *  fodder across three factions moves together). Packages graft their own\n *  bands via registerPresenceBand. */\nexport const PRESENCE_BANDS: Record<string, LevelEnvelope> = {\n  /** Teaching-tier fodder: full through 10, dispersed by 14. */\n  early_only: { to: 10, fadeOut: 4 },\n  /** The early game's regulars: thin out through the teens. */\n  early: { to: 16, fadeOut: 8 },\n  /** The mid-game band: arrives by 8, yields the field past 30. */\n  mid: { from: 8, fadeIn: 4, to: 30, fadeOut: 12 },\n  /** Late arrivals: absent below 12, at full strength by 20. */\n  late: { from: 20, fadeIn: 8 },\n  /** The elite tier: nothing before 20, full presence by 30. */\n  elite: { from: 30, fadeIn: 10 },\n};\n\n/** Register a named band at boot (content packages, mods). No-op when the\n *  name is already taken unless `overwrite` — first writer wins by default. */\nexport function registerPresenceBand(id: string, env: LevelEnvelope, overwrite = false): void {\n  if (!overwrite && PRESENCE_BANDS[id] !== undefined) return;\n  PRESENCE_BANDS[id] = env;\n}\n\nconst warned = new Set<string>();\n\n/** Resolve a spec to its envelope (missing band name → warn once, always-on). */\nexport function presenceEnvelope(spec: PresenceSpec): LevelEnvelope {\n  if (typeof spec !== 'string') return spec;\n  const env = PRESENCE_BANDS[spec];\n  if (env) return env;\n  if (!warned.has(spec)) {\n    warned.add(spec);\n    console.warn(`[presence] unknown band '${spec}' — treating as always-present`);\n  }\n  return {};\n}\n\nconst clamp01 = (v: number): number => (v < 0 ? 0 : v > 1 ? 1 : v);\n\n/** The envelope, evaluated: how present (0..n multiplier) at `level`. */\nexport function presenceMul(spec: PresenceSpec | undefined, level: number): number {\n  if (spec === undefined) return 1;\n  const env = presenceEnvelope(spec);\n  let m = env.mul ?? 1;\n  if (env.from !== undefined && level < env.from) {\n    const fade = env.fadeIn ?? 0;\n    m *= fade > 0 ? clamp01((level - (env.from - fade)) / fade) : 0;\n  }\n  if (env.to !== undefined && level > env.to) {\n    const fade = env.fadeOut ?? 0;\n    m *= fade > 0 ? clamp01((env.to + fade - level) / fade) : 0;\n  }\n  const stops = env.stops;\n  if (stops && stops.length > 0) {\n    if (level <= stops[0][0]) m *= stops[0][1];\n    else if (level >= stops[stops.length - 1][0]) m *= stops[stops.length - 1][1];\n    else {\n      for (let i = 1; i < stops.length; i++) {\n        if (level <= stops[i][0]) {\n          const [l0, m0] = stops[i - 1];\n          const [l1, m1] = stops[i];\n          m *= l1 === l0 ? m1 : m0 + (m1 - m0) * ((level - l0) / (l1 - l0));\n          break;\n        }\n      }\n    }\n  }\n  return m < 0 ? 0 : m;\n}\n\n/** Fold entry-presence × def-presence into a table's weights at `level`,\n *  returning a NEW table with zero-weight entries dropped. The input array is\n *  returned untouched when nothing carries presence (the common fast path).\n *  A table gated ENTIRELY out falls back to the unshaped input — a spawn\n *  site never starves at runtime (validate.ts flags the authoring instead). */\nexport function presenceTable<T extends PresenceEntry>(\n  table: readonly T[], level: number,\n  defPresenceOf?: (id: string) => PresenceSpec | undefined,\n): readonly T[] {\n  let touched = false;\n  for (const e of table) {\n    if (e.presence !== undefined || defPresenceOf?.(e.id) !== undefined) { touched = true; break; }\n  }\n  if (!touched) return table;\n  const out: T[] = [];\n  for (const e of table) {\n    const w = e.weight\n      * presenceMul(e.presence, level)\n      * presenceMul(defPresenceOf?.(e.id), level);\n    if (w > 0) out.push({ ...e, weight: w });\n  }\n  return out.length > 0 ? out : table;\n}\n";
const ARCHIVED_DIMENSION_SOURCE="// ---------------------------------------------------------------------------\n// DIMENSIONS — parallel worldmasses the run can breach into. The SURFACE is\n// dimension zero; delving cave-within-cave-within-cave breaches the\n// UNDERWORLD: its own zone web, its own biome palette (rivers of flame,\n// black fortresses, pandemonium sprawls — the hell recipes are the same\n// registered layouts/landmarks pouring demon materials), flipped through on\n// the world map as a TAB once discovered (the PoE Acts pattern). A dimension\n// is a registry row: palette + level pressure + label — everything else rides\n// the one generation infrastructure.\n// ---------------------------------------------------------------------------\n\nimport type { MapCoord } from './coords';\nimport { BIOME_FIELD_CFG, fieldBiomePick } from './biomes';\nimport { registerDimensionClimate, type DimensionAxisOverride } from './climate';\nimport type { CourseSpec } from './courses';\n\n/** THE SOULWAY — the River of Souls, UNTETHERED: the souls are bound to no\n *  gate, so the river answers to none (anchor 'strewn' — the course fabric's\n *  strewn law deals instances across the whole underworld chart, pure\n *  f(seed); one may happen to wind past the Hellgate, most will not). Each\n *  instance is a broad, SHORT ribbon: it paints the map's wash — an inland\n *  sea on the hell tab — but never chains zones: chartFrontier funnels every\n *  frontier landing in a corridor to that instance's ONE mint-once megazone\n *  (world/soulriver.ts — feather 0 keeps paint and funnel exactly equal, so\n *  no ordinary soulway zone can ever mint; the biome is a PLACE, each\n *  instance one zone). The flame keeps its spring at the gate; the souls\n *  wander. Declared HERE (a leaf both dimensions and the soulriver module\n *  may import — the soulriver leaf pulls it for its corridor/seat/port\n *  math). */\nexport const SOULWAY_COURSE: CourseSpec = {\n  id: 'soulway', biome: 'soulway', anchor: 'strewn',\n  strew: { span: 1400, chance: 0.55 },\n  length: 980, halfWidth: 84, feather: 0, strength: 1,\n  waves: 1.1, sweep: 150, wobble: 34,\n  seedSalt: 0x50f7a,\n  label: 'The River of Souls',\n};\n\n/** How a dimension is ENTERED — data, not a bespoke function. 'cave_breach' =\n *  delving minDepth caves deep tears a breach whose realm gate mints the\n *  dimension's GATE ZONE (the Underworld's ladder). New entry KINDS are engine\n *  seams (a shrine rite, a stormfront, a death); WHICH dimension uses which —\n *  and its gate's name/biome/seed — is declared here, so a heaven or limbo\n *  layer is a registry row away. */\nexport interface DimensionEntry {\n  kind: 'cave_breach' | (string & {});\n  /** cave_breach: nesting depth at which the breach may tear (parent caves\n   *  in a dimensioned world never re-breach — hell's caves are just caves). */\n  minDepth?: number;\n  /** The minted GATE ZONE — the one legal cross-dimension road. */\n  gate: {\n    /** Stable zone id (mint-once; the waypoint home). */\n    id: string;\n    name: string;\n    /** The gate zone's tileset resolves from this biome's frontier pool. */\n    biome: string;\n    /** Gate seed = manifest.seed ^ seedSalt (deterministic across clients). */\n    seedSalt: number;\n  };\n  /** Does the gate keep a WALKABLE ROAD to its surface anchor (the Hellgate\n   *  pattern — default true)? `false` = the gate mints with NO cross-edge in\n   *  either direction: the dimension touches the world only through its own\n   *  entry mechanism (the Aetherial: geysers up, falls down — a realm you\n   *  could stroll into from a crossroads portal is not a realm above the\n   *  sky). Persisted cross-edges from older saves heal at load. */\n  road?: boolean;\n  /** A DOODAD KIND that stands as this dimension's realm gate wherever a\n   *  layout places one (the Ascent's shining arch at a cloud shelf's far\n   *  end). The engine's realm-gate dwell loop scans zone doodads against\n   *  every registered gateDoodad — data, never a kind literal in world.ts.\n   *  cave_breach entries don't need one (the breach doodad is its own path). */\n  gateDoodad?: string;\n  /** A registered TRAVERSAL id (data/traversals.ts) the gate crossing RIDES:\n   *  dwelling the gate plays the cinematic and the dimension swap fires\n   *  behind its veil (the geyser-mouth pattern) — the Ascent's arch launches\n   *  you upward AGAIN, steadier, and arriving at the gate zone's center\n   *  reads as landing there rather than popping into existence. Omitted =\n   *  the crossing is instant (the Hellgate's breach). */\n  traversal?: string;\n}\n\nexport interface DimensionDef {\n  id: string;\n  label: string;\n  /** SKY EXPOSURE the dimension's zones DERIVE when their def doesn't say\n   *  (data/zones.ts skyOf): 'sheltered' (the default — hell has a roof of\n   *  world) or 'open' (the Aetherial IS the sky: weather fronts, radiance,\n   *  wind and strikes all reach its ground; its cave-pockets still derive\n   *  sheltered off caveDepth). Inline literal union — the nocturne-phases\n   *  idiom — so this leaf never imports the zone vocabulary it feeds. */\n  sky?: 'open' | 'sheltered';\n  /** Map-tab accent + node fallback tint. */\n  color: string;\n  /** The dimension's biome palette (weighted) — what its frontiers mint.\n   *  Undefined = the surface heat map rules (only the surface does this). */\n  biomes?: { biome: string; weight: number }[];\n  /** Flat level pressure on top of the radial field (hell runs hot). */\n  levelBonus?: number;\n  /** CLIMATE AXIS OVERRIDES for this dimension (world/climate.ts): replace an\n   *  axis' resting value and/or layer stack, so the SAME biome-affinity\n   *  machinery paints a structurally different world below (the Underworld\n   *  runs hot and arid — volcanic country pools in its hottest reaches while\n   *  gravelands keep the cooler marches). Registered into the climate leaf at\n   *  registerDimension time; everything else rides the shared field pick. */\n  climate?: Record<string, DimensionAxisOverride>;\n  /** WAYPOINTS in this world-state (default true). `false` = NO zone here\n   *  ever carries one — not the gate, not a frontier roll, and fast-travel\n   *  refuses the whole dimension: the realm must be CROSSED every time\n   *  (persisted defs from older saves heal at load). The Aetherial swears\n   *  this: a waypoint into dissolving ground is a stuck-loop machine, and\n   *  heaven with a shortcut is just a lobby. */\n  waypoints?: boolean;\n  /** This dimension HANGS OVER another (the Nether tie): both webs share the\n   *  one map-coordinate space, so every zone here resolves the nearest\n   *  charted zone of `over` at its own coordinate as the ground beneath it —\n   *  FALLS drop into that zone (landing at the proportional spot you fell\n   *  from), and the understory's windows look down on its actual terrain.\n   *  Separate webs, attached worlds: fly the realm north and the land\n   *  passing below is the north of the world you left. */\n  over?: string;\n  /** PER-DIMENSION EVENT TEMPO — this world-state's own frequency levers.\n   *  densityMul scales every package overlay's ignition here (default 1);\n   *  packages[id] overrides per package (demonic incursions ×2.5 below the\n   *  world, ×0.75 above it). Composed into the GATE each per-dimension\n   *  overlay instance is constructed with (sim.ts), so no overlay code ever\n   *  reads this directly — the biomeEventDensity lesson, one tier up. */\n  events?: { densityMul?: number; packages?: Record<string, number> };\n  /** How this dimension is entered (see DimensionEntry). Omitted = no entry\n   *  of its own (the surface — you start there). */\n  entry?: DimensionEntry;\n  /** Winding biome THROUGHLINES across this dimension's heat map (world/\n   *  courses.ts): each paints its biome along a seeded polyline springing at\n   *  its anchor, guarantees onward frontiers so the artery can be FOLLOWED,\n   *  and can hold terminus rolls at its far end. A course-only biome (listed\n   *  in no palette) exists exclusively along its line — a PLACE, not patches. */\n  courses?: CourseSpec[];\n}\n\n/** The event-tempo multiplier a package's overlay runs at inside a dimension. */\nexport function dimensionPackageTempo(dimId: string, pkgId: string): number {\n  const ev = dimensionDef(dimId).events;\n  return ev?.packages?.[pkgId] ?? ev?.densityMul ?? 1;\n}\n\n/** Every registered dimension whose entry is the given kind — the engine seam\n *  (mintCave's breach roll) scans this instead of naming any dimension. */\nexport function dimensionsEnteredBy(kind: string): DimensionDef[] {\n  return Object.values(DIMENSIONS).filter(d => d.entry?.kind === kind);\n}\n\nconst DIMENSIONS: Record<string, DimensionDef> = {};\n\nexport function registerDimension(def: DimensionDef): void {\n  if (DIMENSIONS[def.id]) console.warn(`[dimensions] re-registering '${def.id}' — overriding`);\n  DIMENSIONS[def.id] = def;\n  if (def.climate) registerDimensionClimate(def.id, def.climate);\n}\n\n/** Add a COURSE to an already-registered dimension — the seam a sibling\n *  fabric registers its arteries through (the relief fabric's surface\n *  rivers), mirroring registerDimensionClimate: the fabric imports the\n *  dimension registry, never the reverse, so the leaf web stays acyclic. */\nexport function registerDimensionCourse(dimId: string, spec: CourseSpec): void {\n  const def = DIMENSIONS[dimId];\n  if (!def) { console.warn(`[dimensions] course '${spec.id}' names unknown dimension '${dimId}'`); return; }\n  (def.courses ??= []).push(spec);\n}\n\nexport function dimensionDef(id: string | undefined): DimensionDef {\n  return DIMENSIONS[id ?? 'surface'] ?? DIMENSIONS.surface;\n}\n\nexport function dimensionIds(): string[] { return Object.keys(DIMENSIONS); }\n\n/** How many frontier roads a dimension's GATE ZONE fans out when it mints\n *  (World.enterDimension) — and therefore the EXACT degree a roadless gate\n *  hub is allowed to hold forever (the load-time heal trims accretion back\n *  to this fan). One constant, two readers, no drift. */\nexport const GATE_FANOUT = 3;\n\n/** Is this zone a dimension's ROADLESS gate hub (DimensionEntry.road ===\n *  false, gate.id match — the Firmament)? Such a hub's edge set is exactly\n *  its minted frontiers, FOREVER: no linker, weaver, or anchor fallback may\n *  forge a road into it. Pure registry read (no persisted flags, nothing to\n *  heal) — structural typing so pure worldgen callers need no ZoneDef import. */\nexport function isRoadlessGateHub(z: { id: string; dimension?: string }): boolean {\n  if (!z.dimension) return false;\n  const ent = dimensionDef(z.dimension)?.entry;\n  return !!ent && ent.road === false && ent.gate.id === z.id;\n}\n\n// THE RIVERS (world/relief.ts) join the surface row via\n// registerDimensionCourse at the relief fabric's module tail — the fabric\n// imports this registry, never the reverse (the acyclic-leaf law).\nregisterDimension({ id: 'surface', label: 'The Surface', color: '#8fb86a' });\nregisterDimension({\n  id: 'underworld', label: 'The Underworld', color: '#d84a2a',\n  // Hell's palette: rift country (river-of-flame riverlands + siege castles),\n  // the OUTER STEPPES (open marches cut by ruined hellwork walls + abyssal\n  // maws — the gate-terrace descent), volcanic cauldrons (spiral over lava),\n  // flesh warrens — all biome rows; the dimension only re-weights WHERE the\n  // world grows from them.\n  biomes: [\n    { biome: 'rift', weight: 4 },\n    { biome: 'steppes', weight: 4 },\n    // THE WARFRONT — the ACTIVE front (Bhorog's siege-works): live\n    // trebuchet batteries, crater country, marching grind-columns. The\n    // war HAPPENING, where the rift's wasteland is the wound it left.\n    { biome: 'warfront', weight: 3 },\n    { biome: 'volcanic', weight: 3 },\n    { biome: 'flesh', weight: 2 },\n    // THE CAUL — the invader: hell-ONLY membrane country (never in the\n    // surface field) pooling where hell runs least arid — the organism\n    // grows where the stone sweats. Its climate affinity carves it a\n    // province of its own the way the steppes' heat-crest does.\n    { biome: 'caul', weight: 2 },\n    // THE DURANCE — the hate-citadel: rare ENCLAVE regions (BiomeInfo.enclave)\n    // that wall themselves behind boundary gates; interiors, not country.\n    { biome: 'durance', weight: 1.5 },\n    { biome: 'grave', weight: 1 },\n  ],\n  levelBonus: 3,\n  // Hell's own climate: hot and arid, with its own slow heat swells — so the\n  // shared affinity machinery pools volcanic country in the hottest reaches\n  // (temperature crests past 'scorching') while gravelands keep the cooler\n  // marches. No seas below: the maritime axis reads 0 everywhere.\n  climate: {\n    temperature: { base: 0.72, layers: [{ kind: 'noise', cell: 900, amp: 0.22, salt: 0x0661 }] },\n    moisture: { base: 0.16, layers: [{ kind: 'noise', cell: 1100, amp: 0.14, salt: 0x0662 }] },\n    maritime: { base: 0, layers: [] },\n  },\n  // Hell's TEMPO: demonic incursions erupt two-and-a-half times as often below\n  // the world as above it — the same package, a different world-state's pulse.\n  events: { packages: { demon_invasion: 2.5 } },\n  // THE RIVER OF FLAME — hell's artery (the D2 Act 4 throughline made real):\n  // a winding course springing at the Hellgate's doorstep, painting the\n  // course-only 'flame' biome down a ~2200-unit meander. Zones minted on it\n  // chain into one followable river (worldgen guarantees onward frontiers +\n  // hands the recipe its up/downstream edges), and the HELLFORGE stands\n  // guaranteed where the river ends. All shape numbers are course data —\n  // tune the meander here, never in engine code.\n  courses: [{\n    id: 'river_of_flame', biome: 'flame', anchor: 'gate',\n    length: 2200, halfWidth: 150, feather: 80, seedSalt: 0xf1a8e,\n    label: 'The River of Flame',\n    terminus: { radius: 260, compositions: [{ composition: 'hellforge_landing', chance: 1 }] },\n  },\n  SOULWAY_COURSE],\n  // Entered by delving: a surface cave ladder FIVE deep — down through the\n  // Galleries and the whole sunless Depths band (world/strata.ts) to the\n  // Brink — tears a breach whose realm gate mints The Hellgate (the one\n  // marked cross-dimension road). The stack reads top to bottom: surface,\n  // caverns, the Depths, the Underworld.\n  // AND — vanishingly rarely — by walking through: the SUNDERING (a rift-\n  // biome composition) plants a standing 'hell_breach' doodad on the\n  // surface, and the gateDoodad scan below turns it into the same crossing\n  // (same Hellgate, same road home — a second door, never a second hell).\n  entry: {\n    kind: 'cave_breach', minDepth: 5,\n    gate: { id: 'uw_gate', name: 'The Hellgate', biome: 'rift', seedSalt: 0x4e11 },\n    gateDoodad: 'hell_breach',\n  },\n});\nregisterDimension({\n  id: 'aetherial', label: 'The Aetherial', color: '#9fc0e8',\n  // The realm ABOVE the weather is not sheltered FROM it: fronts, wind,\n  // strikes and the radiance scalar all reach the shelves and meadows —\n  // the storm wetting the land below is the same storm your prism-span\n  // condenses out of. (Cave-pockets like launch shelves still derive\n  // sheltered off caveDepth — mint them sky:'open' where they shouldn't.)\n  sky: 'open',\n  // The realm above the clouds, two moods wide: the dissolving cloud\n  // SHELVES (the 'aether' torn lattices) and the built HIGH SPIRES (courts\n  // and ephemeral spans — only the fray falls). The FIRMAMENT (the sanctum\n  // biome) is deliberately NOT in the palette: it exists only where the\n  // gate mints it — country grows from shelves and spires; the sanctum is\n  // a place.\n  biomes: [\n    { biome: 'aether', weight: 1 },\n    { biome: 'aether_spires', weight: 0.9 },\n    // THE DRIFTWAYS — the wind country: ground that comes and goes (the\n    // flux fabric). Its climate gate pools it in the realm's wettest\n    // reaches — the storm shelves foretold below.\n    { biome: 'aether_drift', weight: 0.9 },\n    // THE VESPERLANDS — the cosmos country: ground that answers the sky\n    // (the span fabric + radiance-gated comet lanes). Its climate gate\n    // pools it in the realm's coldest reaches — the auroral belt.\n    { biome: 'aether_vesper', weight: 0.9 },\n    // THE HIGH BASTION — the citadel BELT: the Host's outskirts (enormous\n    // silver-and-gold massif architecture, permanent gleamways, clouds\n    // over the clouds). Permanence at altitude — the shelves' opposite —\n    // and now the ring AROUND the true city (its warm gate caps where the\n    // Civitas' begins: the farmland-to-metropolis law in the sky).\n    { biome: 'aether_bastion', weight: 0.9 },\n    // THE CIVITAS — the TRUE angelic city at the warm pole: interlinked\n    // cloud platforms bearing colossal ENTERABLE architecture (the\n    // cathedral generator's family as a whole city), crowned by the\n    // Cathedral of the Highest itself.\n    { biome: 'aether_civitas', weight: 0.75 },\n  ],\n  levelBonus: 4,\n  // The high air: cold, thin, and bone-dry — no seas above the sky. The\n  // shared affinity machinery has one biome to paint today; the axes stand\n  // ready for the realm's future country (auroral tundra-shoals? storm\n  // shelves in the wettest reaches?) to gate against.\n  climate: {\n    temperature: { base: 0.3, layers: [{ kind: 'noise', cell: 1000, amp: 0.18, salt: 0x0ae1 }] },\n    moisture: { base: 0.24, layers: [{ kind: 'noise', cell: 900, amp: 0.2, salt: 0x0ae2 }] },\n    maritime: { base: 0, layers: [] },\n  },\n  // The Host keeps its own weather: world events run at HALF tempo above\n  // the clouds (and the aether biome's own denies gate the worst offenders).\n  events: { densityMul: 0.5 },\n  // THE GALESTREAM — the realm's artery (the wind-river throughline the\n  // shelves foretold; the River of Flame's mirror above the sky): a\n  // jetstream springing at the Firmament's doorstep, painting the\n  // course-only 'aether_stream' biome down a ~2000-unit meander of racing\n  // flux — carrier rafts on the current, gusts with somewhere to be. Zones\n  // minted on it chain into one followable stream, and the VAULT OF DAWN\n  // stands guaranteed where the wind ends — the reward for riding the\n  // whole artery. All shape numbers are course data.\n  courses: [{\n    id: 'galestream', biome: 'aether_stream', anchor: 'gate',\n    length: 2000, halfWidth: 140, feather: 60, seedSalt: 0x9a1e57,\n    waves: 1.7, sweep: 300,\n    label: 'The Galestream',\n    terminus: { radius: 240, compositions: [{ composition: 'vault_of_dawn', chance: 1 }] },\n  }],\n  // NO WAYPOINTS above the clouds: the realm is crossed (geyser up, gate\n  // through, fall out) — never teleported into. A waypoint on a shelf whose\n  // ground dissolves is a rubberband loop waiting to happen; the Firmament\n  // holds the door, not a shortcut.\n  waypoints: false,\n  // THE NETHER TIE: the Aetherial hangs OVER the surface — one coordinate\n  // space, two webs. Falls resolve the nearest charted surface zone at the\n  // faller's own coordinate; the understory shows that zone's true ground.\n  over: 'surface',\n  // Entered by RIDING A SKY GEYSER (the Ascent): the launch drops you on a\n  // collapsing shelf hung over the very zone you left; crossing its eroding\n  // causeway to the ASCENDANT GATE (entry.gateDoodad — the realm-gate dwell\n  // loop scans it) mints The Firmament, the waypoint home the realm's own\n  // frontiers grow from. The structural inverse of the Underworld's breach:\n  // hell is delved into; heaven must be survived INTO.\n  entry: {\n    kind: 'sky_launch',\n    gate: { id: 'ae_gate', name: 'The Firmament', biome: 'aether_sanctum', seedSalt: 0xa54c }, // 'ASCent'\n    gateDoodad: 'ascendant_gate',\n    // The arch is a SECOND launch, steadier: the shelf drops away and the\n    // veil clears on sanctum ground — why every arrival stands at the\n    // Firmament's heart (loadZone centers a from-less entry) instead of at\n    // some door. The lore and the mechanics agree on purpose.\n    traversal: 'firmament_ascent',\n    // NO ROAD DOWN: heaven is not a neighborhood. The realm touches the\n    // world through geysers and falls alone — the Firmament keeps no\n    // walkable edge to the surface (and older saves' edges heal at load).\n    road: false,\n  },\n});\n\nfunction hashCell(a: number, b: number, seed: number): number {\n  let h = (seed ^ 0x9e3779b9) >>> 0;\n  h = Math.imul(h ^ (a | 0), 0x85ebca6b) >>> 0;\n  h = Math.imul(h ^ (b | 0), 0xc2b2ae35) >>> 0;\n  h ^= h >>> 13; h = Math.imul(h, 0x27d4eb2f) >>> 0; h ^= h >>> 15;\n  return h >>> 0;\n}\n\n/** A dimension's biome at a coordinate — the same jittered-Voronoi idiom as\n *  the surface heat map, drawn over the DIMENSION'S palette and picked through\n *  the SHARED weight × climate-affinity machinery (fieldBiomePick), under the\n *  dimension's own axis overrides. Pure/deterministic. */\nexport function dimensionBiomeAt(dimId: string, coord: MapCoord, seed: number): string {\n  const def = dimensionDef(dimId);\n  const table = def.biomes;\n  if (!table?.length) return 'grove';\n  const span = BIOME_FIELD_CFG.cellSpan, jit = BIOME_FIELD_CFG.jitter;\n  const cx = Math.floor(coord.x / span), cy = Math.floor(coord.y / span);\n  let bestGx = cx, bestGy = cy, bestPx = coord.x, bestPy = coord.y, bd = Infinity;\n  for (let dx = -1; dx <= 1; dx++) {\n    for (let dy = -1; dy <= 1; dy++) {\n      const gx = cx + dx, gy = cy + dy;\n      const h = hashCell(gx, gy, seed);\n      const px = (gx + 0.5 + (((h & 0xffff) / 0xffff) - 0.5) * jit) * span;\n      const py = (gy + 0.5 + ((((h >>> 16) & 0xffff) / 0xffff) - 0.5) * jit) * span;\n      const d = (px - coord.x) ** 2 + (py - coord.y) ** 2;\n      if (d < bd) { bd = d; bestGx = gx; bestGy = gy; bestPx = px; bestPy = py; }\n    }\n  }\n  return fieldBiomePick(table, bestGx, bestGy, { x: bestPx, y: bestPy }, seed, dimId);\n}\n\n/** How DEEP into its region a coordinate sits on a DIMENSION's own field —\n *  1 at the jittered Voronoi seat, →0 at the boundary: the surface\n *  biomeDepth mirrored over dimensionBiomeAt's exact cell math, so a realm\n *  COUNTRY can stage its faces (the High Bastion rim → Seraphal heart)\n *  through the same depthAffinity envelopes the desert and the marine\n *  shelves read below. Pure + deterministic. */\nexport function dimensionBiomeDepth(dimId: string, coord: MapCoord, seed: number): number {\n  const def = dimensionDef(dimId);\n  if (!def.biomes?.length) return 0;\n  const span = BIOME_FIELD_CFG.cellSpan, jit = BIOME_FIELD_CFG.jitter;\n  const cx = Math.floor(coord.x / span), cy = Math.floor(coord.y / span);\n  let bd = Infinity;\n  for (let dx = -1; dx <= 1; dx++) {\n    for (let dy = -1; dy <= 1; dy++) {\n      const gx = cx + dx, gy = cy + dy;\n      const h = hashCell(gx, gy, seed);\n      const px = (gx + 0.5 + (((h & 0xffff) / 0xffff) - 0.5) * jit) * span;\n      const py = (gy + 0.5 + ((((h >>> 16) & 0xffff) / 0xffff) - 0.5) * jit) * span;\n      const d = (px - coord.x) ** 2 + (py - coord.y) ** 2;\n      if (d < bd) bd = d;\n    }\n  }\n  return Math.max(0, Math.min(1, 1 - Math.sqrt(bd) / (span * 0.5)));\n}\n";
