 const source=(owner?ownerSource:archive)+'\nexport const __sourceTestRegistry={axes:CLIMATE_AXES,bands:CLIMATE_BANDS,dimensions:DIMENSION_CLIMATE,climate:CLIMATE_CFG};\n';
